5	namespace App\Console\Commands;
6	
7	use App\Models\Category1;
8	use App\Support\XlsxFillColorReader;
9	use AtrioTeam\DigitalHub\Tags\Enum\TagTarget;
10	use AtrioTeam\DigitalHub\Tags\Models\Tag;
11	use AtrioTeam\DigitalHub\Tags\Models\TagCategory;
12	use AtrioTeam\DigitalHub\Tags\Models\TagGroup;
13	use Illuminate\Console\Command;
14	use Illuminate\Support\Facades\DB;
15	use OpenSpout\Reader\XLSX\Options;
16	use OpenSpout\Reader\XLSX\Reader;
17	
18	/**
19	 * Import dei tag anagrafica dei tessuti dal foglio "Tessuti" del file filtri
20	 * INTERIOR (`INTERIOR - materiali e tessuti filtri.xlsx`).
21	 *
22	 * Il foglio è a colonna singola: righe intestazione di blocco (Tipologia,
23	 * Colori, Proprietà, Categoria, Moodboard, Tipo disegno) seguite dai valori;
24	 * le righe separatore (`____`) e vuote vengono ignorate. Per le righe del
25	 * blocco "Colori" la colonna B ha lo sfondo colorato con lo swatch del colore:
26	 * viene letto (XlsxFillColorReader) e salvato sul tag (`color`, #RRGGBB).
27	 *
28	 * Ogni blocco diventa una TagCategory (identificata dallo slug) dentro il
29	 * gruppo "Filtri Tessuti Indoor" (entity_type=fabric, target=entity, Category1
30	 * Indoor), ogni valore un Tag della categoria. Idempotente: categorie e tag
31	 * esistenti vengono aggiornati.
32	 */
33	class ImportIndoorFiltriTessuti extends Command
34	{
35	    protected $signature = 'app:import-indoor-filtri-tessuti '
36	        . '{--file=storage/app/private/import/indoor/materiali-tessuti/INTERIOR - materiali e tessuti filtri.xlsx} '
37	        . '{--fresh : Svuota i tag delle categorie interessate prima di reimportare}';
38	
39	    protected $description = 'Import dei tag anagrafica tessuti dal file filtri INTERIOR (foglio "Tessuti")';
40	
41	    private const SHEET = 'Tessuti';
42	
43	    /** Colonna con lo sfondo colorato accanto ai valori del blocco "Colori". */
44	    private const COLOR_COLUMN = 'B';
45	
46	    /**
47	     * Intestazioni di blocco (chiave normalizzata) → slug stabile e nome
48	     * visualizzato della TagCategory (che può differire dall'intestazione del
49	     * foglio, es. "Categoria" → "Categoria di prezzo"). Nel foglio compaiono
50	     * con casing misto (es. "CATEGORIA").
51	     *
52	     * @var array<string, array{slug: string, name: string}>
53	     */
54	    private const BLOCKS = [
55	        'tipologia' => ['slug' => 'tipologia', 'name' => 'Tipologia'],
56	        'colori' => ['slug' => 'colori', 'name' => 'Colori'],
57	        'proprietà' => ['slug' => 'proprieta', 'name' => 'Proprietà'],
58	        'categoria' => ['slug' => 'categoria', 'name' => 'Categoria di prezzo'],
59	        'moodboard' => ['slug' => 'moodboard', 'name' => 'Moodboard'],
60	        'tipo disegno' => ['slug' => 'tipo-disegno', 'name' => 'Tipo disegno'],
61	    ];
62	
63	    public function handle(): int
64	    {
65	        $file = (string) $this->option('file');
66	        if (! is_file($file)) {
67	            $this->error("File non trovato: {$file}");
68	
69	            return self::FAILURE;
70	        }
71	
72	        $blocks = $this->parseSheet($file);
73	        if ($blocks === null) {
74	            $this->error('Foglio "' . self::SHEET . '" non trovato nel file.');
75	
76	            return self::FAILURE;
77	        }
78	
79	        $stats = ['categories' => 0, 'tags' => 0, 'colors' => 0];
80	
81	        DB::transaction(function () use ($blocks, &$stats): void {
82	            $group = $this->resolveGroup();
83	
84	            $names = array_column(self::BLOCKS, 'name', 'slug');
85	
86	            $categorySort = 0;
87	            foreach ($blocks as $slug => $values) {
88	                $name = $names[$slug];
89	                $category = TagCategory::query()->updateOrCreate(
90	                    ['tag_group_id' => $group->id, 'slug' => $slug],
91	                    ['name' => ['it' => $name, 'en' => $name], 'sort' => $categorySort++],
92	                );
93	                $stats['categories']++;
94	
95	                if ($this->option('fresh')) {
96	                    Tag::query()->where('tag_category_id', $category->id)->delete();
97	                }
98	
99	                foreach ($values as ['value' => $value, 'color' => $color]) {
100	                    /** @var Tag|null $tag */
101	                    $tag = Tag::query()
102	                        ->where('tag_category_id', $category->id)
103	                        ->where('name->it', $value)
104	                        ->first();
105	
106	                    if ($tag === null) {
107	                        $tag = new Tag();
108	                        $tag->tag_category_id = $category->id;
109	                    }
110	                    $tag->setTranslations('name', ['it' => $value, 'en' => $value]);
111	                    $tag->color = $color;
112	                    $tag->save();
113	                    $stats['tags']++;
114	                    if ($color !== null) {
115	                        $stats['colors']++;
116	                    }
117	                }
118	            }
119	        });
120	
121	        $this->info('Import tag tessuti completato.');
122	        $this->table(
123	            ['Metrica', 'Valore'],
124	            collect($stats)->map(fn ($v, $k): array => [$k, $v])->values()->all(),
125	        );
126	
127	        return self::SUCCESS;
128	    }
129	
130	    /**
131	     * Legge il foglio Tessuti e raggruppa i valori per blocco (chiave: slug
132	     * della TagCategory), con l'eventuale colore swatch della riga (sfondo
133	     * della colonna B, blocco "Colori"). Ritorna null se il foglio non esiste.
134	     *
135	     * @return array<string, list<array{value: string, color: string|null}>>|null
136	     */
137	    private function parseSheet(string $file): ?array
138	    {
139	        $blocks = null;
140	        $current = null;
141	
142	        $rowColors = (new XlsxFillColorReader())->read($file, self::SHEET, self::COLOR_COLUMN);
143	
144	        // preserva le righe vuote così l'indice del RowIterator coincide con
145	        // il numero di riga reale del foglio (chiave di $rowColors)
146	        $options = new Options();
147	        $options->SHOULD_PRESERVE_EMPTY_ROWS = true;
148	
149	        $reader = new Reader($options);
150	        $reader->open($file);
151	        foreach ($reader->getSheetIterator() as $sheet) {
152	            if ($sheet->getName() !== self::SHEET) {
153	                continue;
154	            }
155	            $blocks = [];
156	
157	            /** @var int $rowNumber */
158	            foreach ($sheet->getRowIterator() as $rowNumber => $row) {
159	                $cell = $row->getCells()[0] ?? null;
160	                $raw = $cell?->getValue();
161	                $value = is_scalar($raw) ? trim((string) $raw) : '';
162	
163	                // righe vuote e separatori (____) tra i gruppi di colori
164	                if ($value === '' || preg_match('/^_+$/', $value) === 1) {
165	                    continue;
166	                }
167	
168	                $block = self::BLOCKS[$this->normalize($value)] ?? null;
169	                if ($block !== null) {
170	                    $current = $block['slug'];
171	                    $blocks[$current] ??= [];
172	
173	                    continue;
174	                }
175	
176	                if ($current === null) {
177	                    $this->warn("Valore fuori da ogni blocco, ignorato: {$value}");
178	
179	                    continue;
180	                }
181	
182	                $blocks[$current][] = ['value' => $value, 'color' => $rowColors[$rowNumber] ?? null];
183	            }
184	
185	            break;
186	        }
187	        $reader->close();
188	
189	        return $blocks;
190	    }
191	
192	    /**
193	     * Gruppo tag anagrafica dei tessuti Indoor (creato se assente).
194	     * Fallisce se la Category1 Indoor (slug stabile, il nome può cambiare)
195	     * non esiste.
196	     */
197	    private function resolveGroup(): TagGroup
198	    {
199	        $indoor = Category1::query()->where('slug', 'indoor')->firstOrFail();
200	
201	        return TagGroup::query()
202	            ->where('entity_type', 'fabric')
203	            ->where('target', TagTarget::Entity)
204	            ->where('category_1_id', $indoor->id)
205	            ->first()
206	            ?? TagGroup::query()->create([
207	                'entity_type' => 'fabric',
208	                'target' => TagTarget::Entity,
209	                'category_1_id' => $indoor->id,
210	                'name' => ['it' => 'Filtri Tessuti Interior', 'en' => 'Interior fabric filters'],
211	            ]);
212	    }
213	
214	    private function normalize(string $value): string
215	    {
216	        return trim((string) preg_replace('/\s+/', ' ', mb_strtolower($value)));
217	    }
218	}
